I like this suggestion.. But up to you.. I got confused reading this.. 


```
static bool applyTlsProfile(OpenSSLSSLCtx& sslCtx)
{
    if constexpr (BMCWEB_TLS_PROFILE == "modern")
    {
        if (!sslCtx.setCurves(mozillaModernCurves))
        {
            return false;
        }

        if (!sslCtx.setCiphersuites(mozillaModernCiphersuites))
        {
            return false;
        }

        return true;
    }

    if constexpr (BMCWEB_TLS_PROFILE == "intermediate")
    {
        if (!sslCtx.setCurves(mozillaIntermediateCurves))
        {
            return false;
        }

        if (!sslCtx.setCipherList(mozillaIntermediateCiphers))
        {
            return false;
        }

        if (!sslCtx.setCiphersuites(mozillaIntermediateCiphersuites))
        {
            return false;
        }

        return true;
    }

    return false;
}
```
